// Regenerates api/_lib/confirmation-template.js from templates/client-confirmation.html.
// templates/ is excluded by .vercelignore, so the function reads the inlined copy instead.
// Run after editing the template:  node tools/build-email-template.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const html = fs.readFileSync(path.join(root, 'templates/client-confirmation.html'), 'utf8');
const out =
  '// GENERATED by tools/build-email-template.js from templates/client-confirmation.html. Do not edit by hand.\n' +
  'module.exports = ' + JSON.stringify(html) + ';\n';
fs.writeFileSync(path.join(root, 'api/_lib/confirmation-template.js'), out);
console.log('wrote api/_lib/confirmation-template.js (' + html.length + ' chars)');
